import { prepareOffline, paintOffline } from './offline.js?v=20261030-3';
import { ILLUSTRATIONS } from './illustrations.js?v=20261030-3';
import { MNEMONICS, MNEMONIC_SOURCES } from './mnemonics.js?v=20261030-3';
import { makeTimeline, filterTimeline, timelinePage, paginateTimeline, fitTimelineLabels, TIMELINE_LABELS } from './timeline.js?v=20261030-3';
import { celebrationFor } from './celebration.js?v=20261030-3';
import { DATA } from './data.js';
import { highlightMnemonic } from './study.js?v=20261030-3';
import { GLOSSARY } from './glossary.js?v=20261030-3';
import { buildSession, shuffle } from './engine.js?v=20261030-3';
import { LENGTHS, MODES, REWARDS, normaliseRewards, stageCount, isUnlocked, hasCleared, isAllClear, nextChallenge, awardCompletion, scoreMessage } from './rewards.js?v=20261030-3';

const app=document.querySelector('#app');
const KEY='history-era-cards-v1';
const icons={cards:'<rect x="6" y="3" width="14" height="16" rx="2"/><path d="m6 7-3 1v12a2 2 0 0 0 2 2l10-2"/>',test:'<path d="M9 4h6l1 2h3v15H5V6h3z"/><path d="m8 13 2 2 5-5M9 4V2h6v2"/>',list:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 3v18M11 8h7M11 12h7M11 16h7"/>',flip:'<path d="M4 8a8 8 0 0 1 14-3l2 3M20 3v5h-5M20 16A8 8 0 0 1 6 19l-2-3M4 21v-5h5"/>',left:'<path d="m14 5-7 7 7 7"/>',right:'<path d="m10 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',again:'<path d="M4 10a8 8 0 1 1 2 8M4 4v6h6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',shuffle:'<path d="m3 4 18 16m-5 0h5v-5M3 20l7-7m4-4 7-5m-5 0h5v5"/>'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
let progress={cards:{},tests:[],rewards:{}};
try{const p=JSON.parse(localStorage.getItem(KEY)||'null');if(p){progress.rewards=normaliseRewards(p.rewards);if(p.rewards&&!p.rewards.version)progress.legacyRewards=p.rewards;else if(p.legacyRewards)progress.legacyRewards=p.legacyRewards;}if(p&&typeof p.cards==='object'&&p.cards!==null){progress.cards=Object.fromEntries(Object.entries(p.cards).filter(([id,s])=>DATA.some(x=>x.id===id)&&['known','review'].includes(s)));if(Array.isArray(p.tests))progress.tests=p.tests.filter(x=>x&&Number.isFinite(x.correct)&&Number.isFinite(x.total)).slice(-20);}}catch{storageOK=false;}
const state={view:'catalog',region:'japan',order:'chronological',filter:'all',deck:[],index:0,flipped:true,browse:false,testMode:'world-japan',testLength:3,session:null,result:null,query:'',catalogPage:0,pickerPage:0,catalogSize:8,timelineLayout:null,pickerSize:12,recordsLength:3,resultTab:'summary',reviewIndex:0};
const labels={world:'世界史',japan:'日本史'};
const modeNames={'world-japan':'世界史 → 日本史','japan-world':'日本史 → 世界史',random:'ランダム'};
const initialChallenge=nextChallenge(progress.rewards);if(initialChallenge){state.testLength=initialChallenge.length;state.testMode=initialChallenge.mode;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(progress));}catch{storageOK=false;}}
function rebuildDeck(){let rows=DATA.filter(x=>x.region===state.region).sort((a,b)=>a.year-b.year);if(state.order==='shuffle')rows=shuffle(rows);state.deck=rows;state.index=0;state.flipped=true;}
function visibleDeck(){return state.deck.filter(x=>state.filter==='all'||state.filter==='known'&&progress.cards[x.id]==='known'||state.filter==='review'&&progress.cards[x.id]==='review'||state.filter==='unlearned'&&progress.cards[x.id]!=='known');}
rebuildDeck();
const timelineData=makeTimeline(DATA);
function badge(region){return `<span class="badge ${region}"><span class="dot" style="background:currentColor"></span>${labels[region]}</span>`;}
function tabs(name,choices,current){return `<div class="tabs" role="group" aria-label="${esc(name)}">${choices.map(([value,label])=>`<button data-action="${esc(name)}" data-value="${esc(value)}" class="${current===value?'active':''}" aria-pressed="${current===value}">${label}</button>`).join('')}</div>`;}
function heading(eyebrow,title,sub,pill=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p></div>${pill?`<span class="quiet-pill">${pill}</span>`:''}</div>`;}
function shell(body){const active=state.view==='picker'?'study':state.view==='records'?'test':state.view;const length=active==='test'?(state.view==='records'?state.recordsLength:state.session?.courseLength||state.result?.courseLength||state.testLength):null;return `<div class="shell ${length?`course-theme course-${length}`:''}"><header class="header"><div class="brand"><span class="brand-mark" aria-hidden="true"></span><div><div class="brand-title">高校受験 同時代史攻略</div><div class="brand-sub">日本と世界を、時間でつなぐ。</div></div></div><nav aria-label="学習メニュー">${[['catalog','list','年表'],['study','cards','暗記カード'],['test','test','テスト']].map(([v,i,t])=>`<button class="nav-item ${active===v?'active':''}" data-action="view" data-value="${v}" ${active===v?'aria-current="page"':''}>${icon(i,18)}<span>${t}</span></button>`).join('')}</nav></header><main id="main">${!storageOK?'<div class="storage-note">このブラウザでは学習記録を保存できません。</div>':''}${body}</main><footer class="app-footer"><span>世界史 30項目 ・ 日本史 50項目</span><button class="offline-button" data-action="offline" aria-live="polite">オフライン準備</button></footer></div>`;}
function pager(key,page,size,total){const pages=Math.max(1,Math.ceil(total/size));return `<div class="pager"><button class="btn" data-action="page" data-value="${key}:${page-1}" ${page===0?'disabled':''}>${icon('left',16)} 前へ</button><span class="position" aria-live="polite">${page+1} ／ ${pages} ページ<span class="page-range">　${total?`${page*size+1}–${Math.min((page+1)*size,total)} ／ ${total}枚`:'0枚'}</span></span><button class="btn" data-action="page" data-value="${key}:${page+1}" ${page>=pages-1?'disabled':''}>次へ ${icon('right',16)}</button></div>`;}
function picker(){const rows=visibleDeck(),size=state.pickerSize;state.pickerPage=Math.min(state.pickerPage,Math.max(0,Math.ceil(rows.length/size)-1));return heading('CHOOSE A CARD',`${labels[state.region]}のカードを選ぶ`,'年号をタッチすると、そのカードから始められます。')+`<section class="panel paged-panel"><div class="panel-top"><span>${rows.length}枚 ・ ${state.order==='shuffle'?'シャッフル順':'年代順'}</span><button class="btn" data-action="view" data-value="study">暗記に戻る</button></div><div class="paged-grid picker-grid" data-grid="picker">${rows.slice(state.pickerPage*size,(state.pickerPage+1)*size).map((x,i)=>`<button class="browse-card ${state.pickerPage*size+i===state.index?'selected':''}" data-action="pick" data-value="${state.pickerPage*size+i}"><strong>${x.year}<small>年</small></strong><span>${progress.cards[x.id]==='known'?'覚えた':progress.cards[x.id]==='review'?'もう一度':'未習得'}</span></button>`).join('')}</div>${pager('picker',state.pickerPage,size,rows.length)}</section>`;}

function mnemonicCredit(item){const m=MNEMONICS[item.id],source=MNEMONIC_SOURCES[m.source];return source?`<span class="mnemonic-credit">出典：${esc(source.name)}</span>`:'<span class="mnemonic-credit">語呂：作例</span>';}
function mnemonicFace(item,index,total){const m=MNEMONICS[item.id],art=ILLUSTRATIONS[item.id];return `<span class="anime-art-frame"><img class="anime-art" src="${esc(art.src)}" width="1536" height="1024" alt="${esc(art.description)}" decoding="async" fetchpriority="high"></span><span class="anime-copy"><span class="front-head"><span class="year-number">${item.year}<small>年</small></span><span class="front-meta">${badge(item.region)}<span class="position">${index+1} ／ ${total}</span><span class="tap-note">タッチで出来事へ</span></span></span><span class="mnemonic-bubble"><strong class="mnemonic-cue">${esc(art.cue)}</strong><span class="mnemonic-text">${highlightMnemonic(item.id,m.text)}</span></span><span class="mnemonic-parts" aria-label="読みと数字の対応">${m.parts.map(p=>`<span><b>${esc(p.reading)}</b><small>${esc(p.digits)}</small></span>`).join('<i aria-hidden="true">・</i>')}</span></span>`;}

function eventFace(item){const note=GLOSSARY[item.id];return `<span class="event-copy"><span class="flash-event">${esc(item.event)}</span>${note?`<span class="event-glossary" id="event-glossary"><span class="glossary-label">用語メモ</span><strong>${esc(note.term)}</strong><span>${esc(note.text)}</span></span>`:''}</span>`;}

function study(){
 const rows=visibleDeck();state.index=Math.min(Math.max(0,state.index),Math.max(0,rows.length-1));const item=rows[state.index];
 const all=DATA.filter(x=>x.region===state.region),known=all.filter(x=>progress.cards[x.id]==='known').length;
 return heading('MEMORIZE','めくって、覚える。','出来事から年号を考え、めくって答え合わせ。')+`<section class="panel study-panel"><div class="panel-top">${tabs('region',[['japan','日本史 <small>50</small>'],['world','世界史 <small>30</small>']],state.region)}<div class="field-select"><select id="order" aria-label="カードの順番"><option value="chronological" ${state.order==='chronological'?'selected':''}>年代順</option><option value="shuffle" ${state.order==='shuffle'?'selected':''}>シャッフル</option></select><select id="filter" aria-label="学習状態で絞り込む">${[['all','すべて'],['unlearned','未習得'],['review','もう一度'],['known','覚えた']].map(([v,t])=>`<option value="${v}" ${state.filter===v?'selected':''}>${t}</option>`).join('')}</select></div></div>${item?`<div class="flip-wrap"><button class="flashcard ${state.flipped?'is-flipped':''}" id="flashcard" data-action="flip" aria-label="${state.flipped?`${esc(item.event)}。タッチで年号と語呂を確認`:`${item.year}年。タッチで出来事を見る`}" aria-pressed="${state.flipped}" ${state.flipped&&GLOSSARY[item.id]?'aria-describedby="event-glossary"':''}><span class="flipper"><span class="card-face front" aria-hidden="${state.flipped}">${mnemonicFace(item,state.index,rows.length)}</span><span class="card-face back" aria-hidden="${!state.flipped}"><span class="card-corner"><span>何年の出来事？</span><span>EVENT</span></span>${eventFace(item)}</span></span></button></div><div class="study-actions"><button class="btn icon" data-action="prev" aria-label="前のカード" ${rows.length<2?'disabled':''}>${icon('left')}</button><button class="btn review wide" data-action="remember" data-value="review" ${state.flipped?'disabled':''}>${icon('again',16)}もう一度</button><button class="btn primary wide" data-action="remember" data-value="known" ${state.flipped?'disabled':''}>${icon('check',16)}覚えた</button><button class="btn icon" data-action="next" aria-label="次のカード" ${rows.length<2?'disabled':''}>${icon('right')}</button></div>`:`<div class="empty-state"><h3>この範囲にカードはありません</h3><button class="btn" data-action="show-all">すべてのカードを見る</button></div>`}<div class="study-bottom"><div class="study-progress"><div class="study-progress-meta"><span>覚えた <b>${known}</b> ／ ${all.length}</span>${item?mnemonicCredit(item):''}</div><div class="progress-track" role="progressbar" aria-label="習得率" aria-valuenow="${known}" aria-valuemin="0" aria-valuemax="${all.length}"><span style="width:${known/all.length*100}%"></span></div></div><button class="btn" data-action="picker">カードを選ぶ ${icon('list',16)}</button></div></section>`;
}

function stagePicker(){
 return `<div class="stage-path" role="group" aria-label="問題数と進級状況">${LENGTHS.map((n,i)=>{const count=stageCount(progress.rewards,n),unlocked=isUnlocked(progress.rewards,n);return `<button class="stage-step ${state.testLength===n?'selected':''} ${unlocked?'':'is-locked'} ${count===3?'stage-complete':''}" data-action="test-length" data-value="${n}" ${unlocked?'':'disabled'} aria-pressed="${state.testLength===n}" aria-label="${n}問ステージ、${unlocked?`${count}モード満点クリア`:`${LENGTHS[i-1]}問の３モード満点で解放`}"><span class="stage-step-top">STEP 0${i+1}<span>${count===3?'CLEAR':unlocked?'挑戦可能':'未解放'}</span></span><strong>${n}<small>問</small></strong><span class="stage-step-count">${count} ／ 3 モード 満点</span>${!unlocked?`<span class="stage-step-requirement">${LENGTHS[i-1]}問の印３つで解放</span>`:''}</button>`;}).join('')}</div>`;
}
function testSetup(){const n=state.testLength,count=stageCount(progress.rewards,n);return heading('MASTERY CHALLENGE','満点で、次のステージへ。','３つのモードで満点を取ると、次の問題数が解放されます。')+`<section class="panel setup-panel"><div class="setup-section"><div class="section-label">ステージを選ぶ <span class="course-label">STEP ${String(LENGTHS.indexOf(state.testLength)+1).padStart(2,'0')} ／ ${state.testLength}問</span></div>${stagePicker()}</div><div class="setup-section"><div class="section-label">出題モードを選ぶ</div><div class="mode-grid">${[['world-japan','WORLD → JAPAN','世界史 → 日本史','世界の出来事から、日本の出来事へ。'],['japan-world','JAPAN → WORLD','日本史 → 世界史','日本の出来事から、世界の出来事へ。'],['random','MIXED','ランダム','両方向を混ぜて出題。']].map(([v,en,t,sub])=>`<button class="mode-card ${state.testMode===v?'active':''}" data-action="test-mode" data-value="${v}" aria-pressed="${state.testMode===v}"><span class="mode-icon">${en}</span><strong class="mode-route">${t}</strong><span class="mode-caption">${sub}</span><span class="mode-clear-state ${hasCleared(progress.rewards,n,v)?'done':''}">${hasCleared(progress.rewards,n,v)?'○ 満点クリア済み':'未クリア'}</span></button>`).join('')}</div></div><div class="mastery-rule"><strong>満点だけがクリアです。</strong><span>${n}問の印 ${count} ／ 3。同じモードの再クリア・復習では印は増えません。</span></div><div class="test-note">${n===LENGTHS.at(-1)?'定番の相手を外した４枚から、最も近い出来事を選びます。':'年代が最も近い定番の組み合わせを含めて出題します。'}年号は解答後に表示。</div><div class="test-startbar"><button class="btn" data-action="records">満点の記録</button><button class="btn primary" data-action="start">${n}問に挑戦する ${icon('arrow',18)}</button></div></section>`;}

function questionView(){const s=state.session,q=s.queue[s.index],side=q.source.region==='world'?'japan':'world',answered=!!s.current;
 return heading('CONNECT',modeNames[s.mode],s.courseLength===LENGTHS.at(-1)?'定番の相手を除いた４枚から、最も近い出来事をタッチ。':'４枚の中で、年代が最も近い出来事をタッチ。')+`<section class="panel quiz-panel"><div class="question-top"><span class="test-direction">${badge(q.source.region)} ${icon('arrow',14)} ${labels[side]}</span><span class="position">第 ${s.index+1} 問 ／ ${s.queue.length} 問</span></div><div class="progress-track"><span style="width:${s.index/s.queue.length*100}%"></span></div><div class="question-prompt"><h2>${esc(q.source.event)}${answered?`<span class="source-year">${q.source.year}年</span>`:''}</h2></div><div class="judgement ${answered?(s.current.correct?'is-correct':'is-wrong'):''}" role="status" aria-live="polite">${answered?`<span class="judge-symbol" aria-hidden="true">${s.current.correct?'○':'×'}</span><strong class="judge-label">${s.current.correct?'正解！':'正解を確認しよう'}</strong><span class="judge-detail">${q.source.year}年 ↔ ${q.answer.year}年 ・ ${Math.abs(q.answer.year-q.source.year)}年の差</span>`:`<span>${s.courseLength===LENGTHS.at(-1)?'定番の相手はありません。この４枚で最も近いのは？':'この出来事と、年代が最も近いのは？'}</span>`}</div><div class="choice-grid">${q.options.map((x,i)=>`<button class="choice ${answered?(x.id===q.answer.id?'correct':x.id===s.current.selectedId?'wrong':''):''}" data-action="answer" data-value="${x.id}" ${answered?'disabled':''} aria-label="${esc(x.event)}${answered?`、${x.year}年${x.id===q.answer.id?'、正解':''}`:''}"><span class="choice-top"><span class="choice-number">${i+1}</span>${answered?`<span class="answer-year">${x.year}<small>年</small></span><span class="answer-result">${x.id===q.answer.id?'○ 正解':x.id===s.current.selectedId?'選んだ答え':''}</span>`:''}</span><span class="answer-event">${esc(x.event)}</span></button>`).join('')}</div><div class="test-bottom"><button class="btn" data-action="quit">テストを終了</button><button class="btn primary" data-action="question-next" ${answered?'':'disabled'}>${s.index===s.queue.length-1?'結果を見る':'次の問題へ'} ${icon('right',17)}</button></div></section>`;
}

function rewardArt(kind){
 const drawing={
  stamp:'<rect x="27" y="27" width="106" height="106" rx="6" fill="none" stroke="currentColor" stroke-width="3"/><rect x="34" y="34" width="92" height="92" rx="3" fill="none" stroke="currentColor"/><text x="80" y="90" text-anchor="middle" font-family="Arial,sans-serif" font-size="49" font-weight="600" fill="currentColor">3</text><text x="80" y="113" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" letter-spacing="2" fill="currentColor">PERFECT</text>',
  badge:'<path d="m56 113-9 30 33-13 33 13-9-30" fill="currentColor" opacity=".25"/><path d="m80 19 48 27v56l-48 27-48-27V46Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="m80 27 41 23v47l-41 24-41-24V50Z" fill="none" stroke="currentColor"/><text x="80" y="87" text-anchor="middle" font-family="Arial,sans-serif" font-size="40" fill="currentColor">6</text><text x="80" y="106" text-anchor="middle" font-family="Arial,sans-serif" font-size="8" letter-spacing="1.5" fill="currentColor">PERFECT</text>',
  trophy:'<path d="M49 31h62v30c0 26-14 40-31 40S49 87 49 61Z" fill="none" stroke="currentColor" stroke-width="4"/><path d="M49 41H29v16c0 19 12 25 27 26M111 41h20v16c0 19-12 25-27 26M80 101v24M57 137v-9h46v9Z" fill="none" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/><text x="80" y="76" text-anchor="middle" font-family="Arial,sans-serif" font-size="29" fill="currentColor">10</text>'
 };
 return `<svg class="reward-illustration" viewBox="0 0 160 160" aria-hidden="true">${drawing[kind]||drawing.stamp}</svg>`;
}
function rewardCollection(){const n=state.recordsLength,count=stageCount(progress.rewards,n),unlocked=isUnlocked(progress.rewards,n),total=LENGTHS.reduce((sum,x)=>sum+stageCount(progress.rewards,x),0);return heading('MASTERY RECORDS','満点クリアの記録',`${total} ／ 9 条件 達成${isAllClear(progress.rewards)?' ・ 全ステージ クリア':''}`)+`<section class="panel records-panel"><div class="panel-top">${tabs('records-length',LENGTHS.map(x=>[String(x),`${x}問`]),String(n))}<button class="btn" data-action="view" data-value="test">戻る</button></div><div class="records-title"><h2>${REWARDS[n].name}</h2><span>${count} ／ 3</span></div><div class="mastery-slots reward-${REWARDS[n].theme}">${MODES.map(mode=>{const done=hasCleared(progress.rewards,n,mode);return `<div class="mastery-slot ${done?'done':''}" aria-label="${n}問・${modeNames[mode]}・${done?'満点クリア':'未クリア'}"><div class="mastery-slot-art">${done?rewardArt(REWARDS[n].icon):'<span class="slot-empty">—</span>'}</div><strong>${modeNames[mode]}</strong><span>${done?'満点クリア':'未クリア'}</span></div>`;}).join('')}</div><p class="record-condition">${count===3?n===LENGTHS.at(-1)?'トロフィー３つ。全ステージ クリア。':`${LENGTHS[LENGTHS.indexOf(n)+1]}問への挑戦券を獲得済み。`:unlocked?'３つのモードで、それぞれ満点を取ろう。':`${LENGTHS[LENGTHS.indexOf(n)-1]}問の３モード満点で解放されます。`}</p></section>`;}

function endingView(r,correct){
 const perfect=correct===r.answers.length,celebration=celebrationFor(r),stageClear=celebration&&celebration.kind!=='mode',allClear=celebration?.kind==='final',config=REWARDS[r.courseLength],earned=celebration?r.earned:null,animate=!!celebration&&!r.celebrationPlayed;
 let title,description;
 if(r.review){title=perfect?'復習完了':'復習を続けよう';description='復習だけでは印は増えません。元の問題数すべてに再挑戦して、満点を取ってください。';}
 else if(!perfect){title='未クリア';description=`${r.courseLength}問すべて正解でクリアです。間違えた問題を確認して、もう一度挑戦してください。`;}
 else if(allClear){title='全ステージ<span class="clear-word">ALL CLEAR</span>';description='３モード × ３ステージ、すべて満点。10問トロフィー３つを獲得しました。';}
 else if(stageClear){title=`${r.courseLength}問ステージ<span class="clear-word">CLEAR</span>`;description='３つのモード、すべて満点。次のステージへの挑戦券を獲得しました。';}
 else if(earned){title=`${config.name}を獲得`;description=`${modeNames[r.mode]}を満点クリア。このステージは ${earned.count} ／ 3 です。`;}
 else{title='満点クリア済み';description='このモードの印は獲得済みです。まだクリアしていないモードに挑戦してください。';}
 return `<div class="ending-hero mastery-ending ${!perfect||r.review?'not-cleared reward-review':`reward-${config.theme}`} ${stageClear?'stage-clear':''} ${allClear?'all-clear':''} ${animate?'celebrate-new':''}" ${animate?'data-celebration="'+celebration.kind+'"':''}>${animate?`<div class="celebration-particles" aria-hidden="true">${Array.from({length:stageClear?24:12},(_,i)=>`<i style="--i:${i};--angle:${i*(stageClear?15:30)}deg;--delay:${80+(i%5)*35}ms"></i>`).join('')}</div>`:''}<span class="ending-kicker">${r.review?'REVIEW':allClear?'ALL NINE PERFECT':stageClear?`STAGE ${String(LENGTHS.indexOf(r.courseLength)+1).padStart(2,'0')} COMPLETED`:perfect?'PERFECT CLEAR':'TRY AGAIN'}</span>${!r.review&&perfect?`<div class="reward-art"><span class="impact-ring" aria-hidden="true"></span>${rewardArt(config.icon)}</div>`:'<div class="mastery-result-symbol" aria-hidden="true">'+(perfect?'○':'×')+'</div>'}<h2>${title}</h2><p class="ending-message">${modeNames[r.mode]}</p><div class="score-summary"><strong>${correct}<small> ／ ${r.answers.length} 問正解</small></strong><span>${Math.round(correct/r.answers.length*100)}%</span></div><p class="ending-detail">${description}</p>${earned?`<div class="earned-modes" aria-label="${r.courseLength}問の満点クリア状況">${MODES.map(mode=>{const done=hasCleared(progress.rewards,r.courseLength,mode);return `<div class="earned-mode ${done?'done':''} ${mode===r.mode?'just-earned':''}"><span class="earned-mini-art">${done?rewardArt(config.icon):'<span class="empty-mark">—</span>'}</span><span>${mode==='world-japan'?'世界→日本':mode==='japan-world'?'日本→世界':'ランダム'}</span></div>`;}).join('')}</div>`:''}${r.unlocked?`<div class="challenge-ticket"><span>CHALLENGE TICKET</span><strong>${r.unlocked}問 挑戦券</strong><small>新しいステージが解放されました</small></div>`:''}${allClear?'<div class="mastery-final-seal">全９条件 達成</div>':''}</div>`;
}
function resultView(){const r=state.result,correct=r.answers.filter(x=>x.correct).length,wrong=r.answers.filter(x=>!x.correct),perfect=wrong.length===0,next=nextChallenge(progress.rewards,r.courseLength);
 const primary=perfect&&!r.review&&next?`<button class="btn primary" data-action="next-challenge">${next.length!==r.courseLength?`${next.length}問に挑戦`:'次の未クリアモードへ'}</button>`:perfect&&!r.review&&!next?'<button class="btn primary" data-action="records">全ステージの記録</button>':'<button class="btn primary" data-action="restart">同じ条件で再挑戦</button>';
 const i=Math.min(state.reviewIndex,r.answers.length-1),a=r.answers[i],q=a.question;
 return heading('RESULT',r.review?'復習結果':`${r.courseLength}問の結果`,modeNames[r.mode])+`<section class="panel result-panel"><div class="panel-top">${tabs('result-tab',[['summary','結果'],['answers','解答を確認']],state.resultTab)}<span class="result-score">${correct} ／ ${r.answers.length} 問正解</span></div><div class="result-content">${state.resultTab==='summary'?endingView(r,correct):`<div class="answer-review"><div class="question-top"><strong class="${a.correct?'good':'miss'}">${a.correct?'○ 正解':'× 不正解'}</strong><span class="position">第 ${i+1} 問 ／ ${r.answers.length} 問</span></div><div class="question-prompt"><h2>${esc(q.source.event)}<span class="source-year">${q.source.year}年</span></h2></div><div class="choice-grid">${q.options.map(x=>`<div class="choice ${x.id===q.answer.id?'correct':x.id===a.selectedId?'wrong':''}"><span class="choice-top"><span class="answer-year">${x.year}<small>年</small></span><span class="answer-result">${x.id===q.answer.id?'○ 正解':x.id===a.selectedId?'選んだ答え':''}</span></span><span class="answer-event">${esc(x.event)}</span></div>`).join('')}</div><div class="pager"><button class="btn" data-action="review-page" data-value="${i-1}" ${i===0?'disabled':''}>${icon('left',16)} 前の解答</button><span class="review-difference">正解との差 ${Math.abs(q.source.year-q.answer.year)}年</span><button class="btn" data-action="review-page" data-value="${i+1}" ${i===r.answers.length-1?'disabled':''}>次の解答 ${icon('right',16)}</button></div></div>`}</div><div class="result-buttons ${state.resultTab==='answers'?'review-buttons':''}">${state.resultTab==='answers'?'<button class="btn" data-action="result-tab" data-value="summary">結果に戻る</button>':`${primary}${wrong.length?'<button class="btn" data-action="retry-wrong">間違いだけ復習</button>':''}<button class="btn" data-action="setup">ステージ選択</button>`}</div></section>`;
}

function catalogRows(){return filterTimeline(timelineData,'all',state.query);}
function timelineCell(items,region,measure=false){return `<div class="timeline-cell ${region}" role="cell">${items.length?items.map(x=>measure?`<span class="timeline-event" data-value="${x.id}">${esc(TIMELINE_LABELS[x.id]||x.event)}</span>`:`<button class="timeline-event" ${state.timelineLayout?.fontSizes?.[x.id]?`style="font-size:${state.timelineLayout.fontSizes[x.id]}px"`:''} data-action="open-card" data-value="${x.id}" title="${esc(x.event)}" aria-label="${x.year}年、${esc(x.event)}を学習する">${esc(TIMELINE_LABELS[x.id]||x.event)}</button>`).join(''):'<span class="timeline-empty" aria-label="収録項目なし">—</span>'}</div>`;}
function rowMarkup(row,measure=false){return `<div class="timeline-row" ${measure?'':'role="row"'} data-year="${row.year}">${timelineCell(row.japan,'japan',measure)}<div class="timeline-year" role="cell">${row.year}<small>年</small></div>${timelineCell(row.world,'world',measure)}</div>`;}
function currentTimelinePages(rows){const years=rows.map(x=>x.year).join(',');if(state.timelineLayout?.years===years)return state.timelineLayout.pages;return Array.from({length:Math.max(1,Math.ceil(rows.length/state.catalogSize))},(_,page)=>({rows:timelinePage(rows,page,state.catalogSize).rows}));}
function catalogResults(){const rows=catalogRows(),parts=currentTimelinePages(rows);state.catalogPage=Math.min(state.catalogPage,parts.length-1);const page=state.catalogPage,pages=parts.length,slice=parts[page].rows;return `<div class="timeline-table" role="table" aria-label="日本史と世界史の年表"><div class="timeline-head" role="row"><span role="columnheader">日本史</span><span role="columnheader">年</span><span role="columnheader">世界史</span></div><div class="timeline-body" role="rowgroup" data-timeline="true">${slice.map(row=>rowMarkup(row)).join('')}${!rows.length?'<div class="timeline-no-results">該当する出来事はありません。検索条件を変更してください。</div>':''}</div></div><div class="pager timeline-pager"><button class="btn" data-action="page" data-value="catalog:${page-1}" ${page===0?'disabled':''}>${icon('left',16)} 前へ</button><span class="position" aria-live="polite">${page+1} ／ ${pages} ページ${slice.length?`<small>${slice[0].year}–${slice.at(-1).year}年</small>`:''}</span><button class="btn" data-action="page" data-value="catalog:${page+1}" ${page>=pages-1?'disabled':''}>次へ ${icon('right',16)}</button></div>`;}
function catalog(){return heading('TIMELINE','日本と世界を、見比べる。','左が日本史、右が世界史。同じ年の出来事を同じ行に並べています。')+`<section class="panel paged-panel timeline-panel"><div class="timeline-controls"><span class="timeline-note">収録80項目 ・ タッチで詳しく</span><input class="search" id="search" type="search" placeholder="年号・出来事を探す" aria-label="年号・出来事を探す" value="${esc(state.query)}"></div><div id="catalog-results">${catalogResults()}</div></section>`;}

let neighboringArt=[];
function preloadStudyArt(){neighboringArt=[];if(state.view!=='study')return;const rows=visibleDeck();if(rows.length<2)return;for(const offset of [-1,1]){const item=rows[(state.index+offset+rows.length)%rows.length];const image=new Image();image.decoding='async';image.src=ILLUSTRATIONS[item.id].src;neighboringArt.push(image);}}
function render(){const searchFocused=document.activeElement?.id==='search',cursor=searchFocused?document.activeElement.selectionStart:null;app.innerHTML=shell(state.view==='study'?study():state.view==='picker'?picker():state.view==='catalog'?catalog():state.view==='records'?rewardCollection():state.session?questionView():state.result?resultView():testSetup());if(state.view==='test'&&state.result&&state.resultTab==='summary')state.result.celebrationPlayed=true;fitGrid();preloadStudyArt();paintOffline();if(searchFocused){const input=app.querySelector('#search');if(input){input.focus({preventScroll:true});if(cursor!==null)input.setSelectionRange(cursor,cursor);}}}
function fitGrid(){const timeline=app.querySelector('[data-timeline]');if(timeline){const r=timeline.getBoundingClientRect(),rows=catalogRows(),years=rows.map(x=>x.year).join(','),font=getComputedStyle(timeline).font,key=`${r.width.toFixed(1)}|${r.height.toFixed(1)}|${font}|${years}`;if(state.timelineLayout?.key===key)return;const anchor=currentTimelinePages(rows)[state.catalogPage]?.rows[0]?.year;const measure=document.createElement('div');measure.className='timeline-body timeline-measure';measure.setAttribute('aria-hidden','true');measure.setAttribute('inert','');Object.assign(measure.style,{position:'fixed',top:'0',left:'0',width:r.width+'px',height:'auto',visibility:'hidden',pointerEvents:'none'});measure.innerHTML=rows.map(row=>rowMarkup(row,true)).join('');document.body.append(measure);const fontSizes=fitTimelineLabels(measure);const heights=[...measure.children].map(x=>Math.ceil(x.getBoundingClientRect().height));measure.remove();const pages=paginateTimeline(rows,heights,Math.floor(r.height)-1);state.timelineLayout={key,years,pages,fontSizes};state.catalogPage=Math.max(0,pages.findIndex(p=>p.rows.some(x=>x.year===anchor)));render();return;}const grid=app.querySelector('[data-grid]');if(!grid)return;const key=grid.dataset.grid,r=grid.getBoundingClientRect(),minWidth=key==='picker'?110:270,minHeight=key==='picker'?74:100;const cols=Math.max(1,Math.min(key==='picker'?7:3,Math.floor((r.width+10)/(minWidth+10)))),rows=Math.max(1,Math.min(5,Math.floor((r.height+10)/(minHeight+10))));grid.style.setProperty('--cols',cols);grid.style.setProperty('--rows',rows);if(state[key+'Size']!==cols*rows){state[key+'Size']=cols*rows;render();}}
let toastTimer;

function toast(text,duration=1500){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),duration);}
function start(queue=null){if(!queue&&!isUnlocked(progress.rewards,state.testLength)){toast('前のステージの３モードを、すべて満点でクリアしてください');return;}state.result=null;state.session={mode:state.testMode,queue:queue||buildSession(state.testMode,state.testLength),courseLength:state.testLength,rewardLength:queue?null:state.testLength,review:!!queue,index:0,answers:[],current:null};state.resultTab='summary';state.reviewIndex=0;render();}
function action(name,value){
 if(name==='offline'){prepareOffline().then(()=>toast('全教材を保存しました。ネットなしで使えます。')).catch(error=>toast(error.message,6500));return;}
 if(name==='view'){state.view=value;if(value==='study')state.flipped=true;render();return;}
 if(name==='picker'){state.pickerPage=Math.floor(state.index/state.pickerSize);state.view='picker';render();return;}
 if(name==='page'){const [key,page]=value.split(':');if(['catalog','picker'].includes(key)){state[key+'Page']=Math.max(0,Number(page)||0);render();}return;}
 if(name==='records'){state.recordsLength=state.result?.courseLength||state.testLength;state.view='records';render();return;}
 if(name==='records-length'){state.recordsLength=Number(value);render();return;}
 if(name==='result-tab'){state.resultTab=value;render();return;}
 if(name==='review-page'){state.reviewIndex=Number(value);render();return;}
 if(name==='region'){state.region=value;rebuildDeck();render();return;}
 if(name==='show-all'){state.filter='all';state.index=0;render();return;}
 if(name==='flip'){const card=document.querySelector('#flashcard');if(!card)return;state.flipped=!state.flipped;card.classList.toggle('is-flipped',state.flipped);card.setAttribute('aria-pressed',String(state.flipped));const item=visibleDeck()[state.index];if(state.flipped&&GLOSSARY[item?.id])card.setAttribute('aria-describedby','event-glossary');else card.removeAttribute('aria-describedby');card.setAttribute('aria-label',state.flipped?'タッチで年号と語呂を確認':'タッチで出来事を見る');card.querySelector('.front').setAttribute('aria-hidden',String(state.flipped));card.querySelector('.back').setAttribute('aria-hidden',String(!state.flipped));document.querySelectorAll('[data-action="remember"]').forEach(b=>b.disabled=state.flipped);return;}
 if(['prev','next','pick'].includes(name)){const rows=visibleDeck();if(!rows.length)return;state.index=name==='pick'?Number(value):(state.index+(name==='next'?1:-1)+rows.length)%rows.length;state.flipped=true;if(name==='pick')state.view='study';render();return;}
 if(name==='remember'){const rows=visibleDeck(),x=rows[state.index];if(!x||state.flipped||!['known','review'].includes(value))return;progress.cards[x.id]=value;save();const after=visibleDeck();if(after.some(a=>a.id===x.id))state.index=(state.index+1)%Math.max(1,after.length);else state.index=state.index%Math.max(1,after.length);state.flipped=true;render();toast(value==='known'?'「覚えた」に記録しました':'「もう一度」に記録しました');return;}
 if(name==='test-mode'){state.testMode=value;render();return;}
 if(name==='test-length'){const n=Number(value);if(!LENGTHS.includes(n)||!isUnlocked(progress.rewards,n))return;state.testLength=n;render();return;}
 if(name==='next-challenge'){const next=nextChallenge(progress.rewards,state.result?.courseLength||state.testLength);if(!next)return;state.testLength=next.length;state.testMode=next.mode;start();return;}
 if(name==='start'||name==='restart'){if(state.result){state.testLength=state.result.courseLength;state.testMode=state.result.mode;}start();return;}
 if(name==='answer'){const s=state.session;if(!s||s.current)return;const q=s.queue[s.index];if(!q.options.some(x=>x.id===value))return;s.current={selectedId:value,correct:value===q.answer.id};s.answers.push({...s.current,question:q});render();return;}
 if(name==='question-next'){const s=state.session;if(!s||!s.current)return;if(s.index===s.queue.length-1){const correct=s.answers.filter(x=>x.correct).length;const award=awardCompletion(progress.rewards,{length:s.rewardLength,mode:s.mode,correct,completed:s.answers.length,review:s.review});progress.rewards=award.rewards;state.result={mode:s.mode,answers:s.answers,courseLength:s.courseLength,review:s.review,earned:award.earned,unlocked:award.unlocked,awardReason:award.reason};progress.tests.push({date:new Date().toISOString(),mode:s.mode,correct,total:s.answers.length});progress.tests=progress.tests.slice(-20);save();state.session=null;state.resultTab='summary';state.reviewIndex=0;}else{s.index++;s.current=null;}render();document.querySelector('.question-prompt h2')?.setAttribute('tabindex','-1');document.querySelector('.question-prompt h2')?.focus({preventScroll:true});return;}
 if(name==='quit'||name==='setup'){state.session=null;state.result=null;render();return;}
 if(name==='retry-wrong'){const result=state.result;if(!result)return;state.testMode=result.mode;state.testLength=result.courseLength;start(shuffle(result.answers.filter(x=>!x.correct).map(x=>x.question)));return;}
 if(name==='open-card'){const x=DATA.find(x=>x.id===value);if(!x)return;state.region=x.region;state.filter='all';state.order='chronological';rebuildDeck();state.index=state.deck.findIndex(y=>y.id===x.id);state.flipped=false;state.view='study';state.resultTab='summary';state.reviewIndex=0;render();return;}
}
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.value);});
app.addEventListener('change',e=>{if(e.target.id==='order'){state.order=e.target.value;rebuildDeck();render();}if(e.target.id==='filter'){state.filter=e.target.value;state.index=0;state.flipped=true;render();}});
app.addEventListener('input',e=>{if(e.target.id!=='search')return;state.query=e.target.value;state.catalogPage=0;document.querySelector('#catalog-results').innerHTML=catalogResults();fitGrid();});
document.addEventListener('keydown',e=>{const tag=document.activeElement.tagName;if(['INPUT','SELECT','TEXTAREA'].includes(tag)||(tag==='BUTTON'&&[' ','Enter'].includes(e.key)))return;if(state.view==='study'&&[' ','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();action(e.key===' '?'flip':e.key==='ArrowLeft'?'prev':'next');}if(state.view==='test'&&state.session){if(!state.session.current&&/^[1-4]$/.test(e.key)){e.preventDefault();action('answer',state.session.queue[state.session.index].options[Number(e.key)-1].id);}else if(state.session.current&&e.key==='Enter'){e.preventDefault();action('question-next');}}});
function viewportFit(){document.documentElement.style.setProperty('--app-height',`${window.visualViewport?.height||window.innerHeight}px`);fitGrid();}
let resizeFrame;function queueFit(){cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(viewportFit);}
window.addEventListener('resize',queueFit);window.visualViewport?.addEventListener('resize',queueFit);
viewportFit();render();
document.fonts?.ready.then(()=>{state.timelineLayout=null;fitGrid();});
